import * as React from "react";
import { CommonProps } from "../../utility/commonProps";
export interface DataTableHeadProps extends React.ComponentPropsWithoutRef<"tbody">, CommonProps {
    /**
     * The content for the head.
     */
    children: React.ReactNode;
}
/**
 * Data Table Head is the container for a row of Data Table Headers.
 *
 * - {@link https://livingdesign.walmart.com/components/data-table/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/data-table/react/ React documentation}
 *
 * ### Content
 *
 * Data Table Head accepts content (a Data Table Row) through the `children` prop.
 *
 * ```tsx
 * <DataTable>
 *   <DataTableHead>
 *     <DataTableRow>
 *       <DataTableHeader>ID</DataTableHeader>
 *       <DataTableHeader>Name</DataTableHeader>
 *       <DataTableHeader>Status</DataTableHeader>
 *     </DataTableRow>
 *   </DataTableHead>
 * </DataTable>
 * ```
 */
export declare const DataTableHead: React.FunctionComponent<DataTableHeadProps>;
